Context("Form")->flags->remove("NumberCheck"); $var = list_random('a'..'n', 'p'..'z', 'A'..'D', 'F'..'N', 'P'..'T', 'V'..'Z'); Context()->variables->are($var => 'Real'); ($a, $b, $c, $d, $e, $f) = (0..9)[NchooseK(10,6)]; for $x ($a, $b, $c, $d, $e, $f) { $x += random(0.1,0.9,0.1); } $given = Formula("$a($b $var - $c) - $d($e $var - $f)"); $abde = $a*$b - $d*$e; $acdf = -$a*$c + $d*$f; $ans = Formula("$abde $var + $acdf");
